// Unified error type for all FFI exports.
// UniFFI 0.31 supports `Result<T, String>` natively, but a proper error enum
// gives better codegen on both Swift and Kotlin and is forward-compatible.
type FfiError struct {
	err error
}

// Convenience method to turn *FfiError into error
// Avoiding treating nil pointer as non nil error interface
func (err *FfiError) AsError() error {
	if err == nil {
		return nil
	} else {
		return err
	}
}

func (err FfiError) Error() string {
	return fmt.Sprintf("FfiError: %s", err.err.Error())
}

func (err FfiError) Unwrap() error {
	return err.err
}

// Err* are used for checking error type with `errors.Is`
var ErrFfiErrorGeneral = fmt.Errorf("FfiErrorGeneral")
var ErrFfiErrorNestOutdated = fmt.Errorf("FfiErrorNestOutdated")
var ErrFfiErrorNestIdentityChanged = fmt.Errorf("FfiErrorNestIdentityChanged")
var ErrFfiErrorIdentitySuperseded = fmt.Errorf("FfiErrorIdentitySuperseded")
var ErrFfiErrorGuardianApprovalRequired = fmt.Errorf("FfiErrorGuardianApprovalRequired")
var ErrFfiErrorAccountLocked = fmt.Errorf("FfiErrorAccountLocked")

// Variant structs
type FfiErrorGeneral struct {
	Msg string
}

func NewFfiErrorGeneral(
	msg string,
) *FfiError {
	return &FfiError{err: &FfiErrorGeneral{
		Msg: msg}}
}

func (e FfiErrorGeneral) destroy() {
	FfiDestroyerString{}.Destroy(e.Msg)
}

func (err FfiErrorGeneral) Error() string {
	return fmt.Sprint("General",
		": ",

		"Msg=",
		err.Msg,
	)
}

func (self FfiErrorGeneral) Is(target error) bool {
	return target == ErrFfiErrorGeneral
}

// The nest is running an **outdated version** and has booted into a degraded
