type FfiConverterFfiError struct{}

var FfiConverterFfiErrorINSTANCE = FfiConverterFfiError{}

func (c FfiConverterFfiError) Lift(eb RustBufferI) *FfiError {
	return LiftFromRustBuffer[*FfiError](c, eb)
}

func (c FfiConverterFfiError) Lower(value *FfiError) C.RustBuffer {
	return LowerIntoRustBuffer[*FfiError](c, value)
}

func (c FfiConverterFfiError) LowerExternal(value *FfiError) ExternalCRustBuffer {
	return RustBufferFromC(LowerIntoRustBuffer[*FfiError](c, value))
}

func (c FfiConverterFfiError) Read(reader io.Reader) *FfiError {
	errorID := readUint32(reader)

	switch errorID {
	case 1:
		return &FfiError{&FfiErrorGeneral{
			Msg: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 2:
		return &FfiError{&FfiErrorNestOutdated{
			Msg: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 3:
		return &FfiError{&FfiErrorNestIdentityChanged{
			Host:      FfiConverterStringINSTANCE.Read(reader),
			PinnedHex: FfiConverterStringINSTANCE.Read(reader),
			SeenHex:   FfiConverterOptionalStringINSTANCE.Read(reader),
		}}
	case 4:
		return &FfiError{&FfiErrorIdentitySuperseded{
			NewActorIdHex: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 5:
		return &FfiError{&FfiErrorGuardianApprovalRequired{
			Msg: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 6:
		return &FfiError{&FfiErrorAccountLocked{
			LockedUntilSecs: FfiConverterUint64INSTANCE.Read(reader),
		}}
	default:
		panic(fmt.Sprintf("Unknown error code %d in FfiConverterFfiError.Read()", errorID))
	}
}

func (c FfiConverterFfiError) Write(writer io.Writer, value *FfiError) {
	switch variantValue := value.err.(type) {
	case *FfiErrorGeneral:
		writeInt32(writer, 1)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Msg)
	case *FfiErrorNestOutdated:
		writeInt32(writer, 2)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Msg)
	case *FfiErrorNestIdentityChanged:
		writeInt32(writer, 3)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Host)
		FfiConverterStringINSTANCE.Write(writer, variantValue.PinnedHex)
		FfiConverterOptionalStringINSTANCE.Write(writer, variantValue.SeenHex)
	case *FfiErrorIdentitySuperseded:
		writeInt32(writer, 4)
		FfiConverterStringINSTANCE.Write(writer, variantValue.NewActorIdHex)
	case *FfiErrorGuardianApprovalRequired:
		writeInt32(writer, 5)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Msg)
	case *FfiErrorAccountLocked:
		writeInt32(writer, 6)
		FfiConverterUint64INSTANCE.Write(writer, variantValue.LockedUntilSecs)
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiConverterFfiError.Write", value))
	}
}

type FfiDestroyerFfiError struct{}

func (_ FfiDestroyerFfiError) Destroy(value *FfiError) {
	switch variantValue := value.err.(type) {
	case FfiErrorGeneral:
		variantValue.destroy()
	case FfiErrorNestOutdated:
		variantValue.destroy()
	case FfiErrorNestIdentityChanged:
		variantValue.destroy()
	case FfiErrorIdentitySuperseded:
		variantValue.destroy()
	case FfiErrorGuardianApprovalRequired:
		variantValue.destroy()
	case FfiErrorAccountLocked:
		variantValue.destroy()
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiDestroyerFfiError.Destroy", value))
	}
}

