// The asked check — the "Check for Updates" door's one round trip — over
// [`fauna_client::update_look::check_for_newer_release_over_http`], against
// this build's own version. `feed_origin` is [`release_feed_origin`] in
// production; `user_agent` names the calling app (`fauna-windows/0.1.2`).
//
// Runs on the crate's tokio runtime (`fauna_uniffi_async::export`): the
// reqwest round trip panics without a reactor.
func CheckForNewerRelease(feedOrigin string, userAgent string) NewerReleaseCheck {
	res, _ := uniffiRustCallAsync[error](
		nil,
		// completeFn
		func(handle C.uint64_t, status *C.RustCallStatus) RustBufferI {
			res := C.ffi_fauna_ffi_rust_future_complete_rust_buffer(handle, status)
			return GoRustBuffer{
				inner: res,
			}
		},
		// liftFn
		func(ffi RustBufferI) NewerReleaseCheck {
			return FfiConverterNewerReleaseCheckINSTANCE.Lift(ffi)
		},
		C.uniffi_fauna_ffi_fn_func_check_for_newer_release(FfiConverterStringINSTANCE.Lower(feedOrigin), FfiConverterStringINSTANCE.Lower(userAgent)),
		// pollFn
		func(handle C.uint64_t, continuation C.UniffiRustFutureContinuationCallback, data C.uint64_t) {
			C.ffi_fauna_ffi_rust_future_poll_rust_buffer(handle, continuation, data)
		},
		// freeFn
		func(handle C.uint64_t) {
			C.ffi_fauna_ffi_rust_future_free_rust_buffer(handle)
		},
	)

	return res
}

